INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task, web) VALUES (40, 10, 'Design: autopilot, docking and towing, dying, saving and sound', 'work', 'done', NULL, '2026-10-14, docs/design.md (Flight: autopilot, grappling and berthing, towing, dying, saving, sound); decisions 32-35; follow-up task 46', 'Third part of `plan 10: game design`: write the second half of the section "Flight" in `docs/design.md`: the autopilot, close-range manoeuvring, towing, dying and what follows, saving, sound, as the plan body specifies.

